<?php
function image_url(?string $src):string{$src=trim((string)$src);if($src!==''&&filter_var($src,FILTER_VALIDATE_URL)&&in_array(strtolower((string)parse_url($src,PHP_URL_SCHEME)),['http','https'],true))return $src;if(preg_match('~^uploads/products/[a-f0-9]{36}\.(?:jpg|png|webp)$~',$src))return url('/'.$src);return url('/assets/rebox-scenes/fresh-meal.jpg');}
if(PHP_SAPI!=='cli'){session_name('rebox_session');session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Lax']);session_start();header("Content-Type: text/html; charset=UTF-8");}spl_autoload_register(function($c){if(str_starts_with($c,'App\\')){$f=__DIR__.'/'.str_replace('\\','/',substr($c,4)).'.php';if(is_file($f))require $f;}});function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function url(string $p=''):string{$b=rtrim(dirname($_SERVER['SCRIPT_NAME']??''),'/');return $b.($p==='/'?'':$p);}function csrf_token():string{if(empty($_SESSION['_csrf']))$_SESSION['_csrf']=bin2hex(random_bytes(32));return $_SESSION['_csrf'];}function csrf_field():string{return '<input type="hidden" name="_csrf" value="'.e(csrf_token()).'">';}function verify_csrf():void{if(!hash_equals($_SESSION['_csrf']??'',$_POST['_csrf']??'')){http_response_code(419);exit('Phiên hết hạn. Tải lại trang.');}}function money(mixed $n):string{return number_format((float)$n,0,',','.').'₫';}function go(string $p):never{header('Location: '.url($p));exit;}
